        }
        if (PQstatus(conn_) != CONNECTION_OK) {
            std::string message = PQerrorMessage(conn_);
            PQfinish(conn_);
            conn_ = nullptr;
            throw std::runtime_error("PostgreSQL connection failed: " + message);
        }
    }

    PostgresConnection(const PostgresConnection&) = delete;
    PostgresConnection& operator=(const PostgresConnection&) = delete;

    PostgresConnection(PostgresConnection&& other) noexcept : conn_(other.conn_) {
        other.conn_ = nullptr;
    }

    PostgresConnection& operator=(PostgresConnection&& other) noexcept {
        if (this != &other) {
            if (conn_ != nullptr) {
                PQfinish(conn_);
            }
            conn_ = other.conn_;
            other.conn_ = nullptr;
        }
        return *this;
    }

    ~PostgresConnection() {
        if (conn_ != nullptr) {
            PQfinish(conn_);
        }
    }

    PGconn* nativeHandle() const noexcept {
        return conn_;
    }

    bool isValid() const noexcept {
        return conn_ != nullptr && PQstatus(conn_) == CONNECTION_OK;
    }

    void execute(const std::string& sql) {
        if (conn_ == nullptr) {
            throw std::runtime_error("Cannot execute query on invalid PostgreSQL connection.");
        }
        PGresult* result = PQexec(conn_, sql.c_str());
        if (result == nullptr) {
            throw std::runtime_error("PQexec returned null result.");
        }
        ExecStatusType status = PQresultStatus(result);
        if (status != PGRES_COMMAND_OK && status != PGRES_TUPLES_OK) {
            std::string message = PQresultErrorMessage(result);
            PQclear(result);
            throw std::runtime_error("PostgreSQL query failed: " + message);
        }
        PQclear(result);
    }

private:
    PGconn* conn_ = nullptr;
};

